-- 100 AI phase-three security hardening; forward-only.
SET @schema_name=DATABASE();
SET @sql=IF(EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_approval' AND COLUMN_NAME='status' AND COLUMN_TYPE NOT LIKE '%consumed%'),'ALTER TABLE `fun_ai_approval` MODIFY COLUMN `status` enum(\'pending\',\'approved\',\'consumed\',\'denied\',\'expired\',\'cancelled\') NOT NULL DEFAULT \'pending\'','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
SET @sql=IF(EXISTS(SELECT 1 FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=@schema_name AND TABLE_NAME='fun_ai_task' AND COLUMN_NAME='sandbox_status' AND COLUMN_TYPE NOT LIKE '%exported%'),'ALTER TABLE `fun_ai_task` MODIFY COLUMN `sandbox_status` enum(\'pending\',\'created\',\'running\',\'exported\',\'cleaned\',\'failed\') NOT NULL DEFAULT \'pending\'','DO 0'); PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;
UPDATE `fun_permission` SET `act`=LOWER(`act`),`code`=LOWER(`code`),`updated_at`=NOW() WHERE `source_type`='admin_web' AND `source_name`='ai_development' AND `obj`='console/development.ai' AND BINARY `act`<>BINARY LOWER(`act`);
UPDATE `fun_casbin_rule` SET `v3`=LOWER(`v3`),`rule_hash`=SHA2(CONCAT_WS(CHAR(31),`ptype`,`v0`,`v1`,`v2`,LOWER(`v3`)),256) WHERE `ptype`='p' AND `v2`='console/development.ai' AND BINARY `v3`<>BINARY LOWER(`v3`);
